import { useState, useRef, useEffect } from "react";
import { useGSAP } from "../hooks/useGSAP";
import { ParticleCanvas, Typewriter, SkillBar, Modal, ParallaxElement, ScrollReveal } from "../components/Shared";
import { CarDrivingGame } from "../components/CarDrivingGame";
import { DevBadge } from "../components/DeveloperMode";
import { PROJECTS, SKILLS, TECH, SERVICES, TIMELINE, TESTIMONIALS } from "../data/content";

// ── 3D Forest Car Environment Component ───────────────────────────────────────
function ForestCarEnvironment({ theme, scrollTo, children }) {
  const canvasRef = useRef(null);
  const [gameStarted, setGameStarted] = useState(false);
  const [carPosition, setCarPosition] = useState({ x: 200, y: 400, rotation: 0 });
  const [cameraOffset, setCameraOffset] = useState({ x: 0, y: 0 });
  const [keys, setKeys] = useState({});

  // 3D perspective constants
  const VANISH_POINT = { x: 200, y: 150 };
  const HORIZON_Y = 100;
  const ROAD_WIDTH = 300;

  // Handle keyboard input
  useEffect(() => {
    const handleKeyDown = (e) => {
      setKeys(prev => ({ ...prev, [e.key]: true }));

      // ESC to exit driving mode
      if (e.key === 'Escape' && gameStarted) {
        setGameStarted(false);
      }
    };

    const handleKeyUp = (e) => {
      setKeys(prev => ({ ...prev, [e.key]: false }));
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [gameStarted]);

  // Update car position based on input
  useEffect(() => {
    if (!gameStarted) return;

    const updateInterval = setInterval(() => {
      setCarPosition(prev => {
        let newX = prev.x;
        let newY = prev.y;
        let newRotation = prev.rotation;

        const speed = 3;
        const rotSpeed = 0.05;

        // Rotation
        if (keys['ArrowLeft']) newRotation -= rotSpeed;
        if (keys['ArrowRight']) newRotation += rotSpeed;

        // Movement based on rotation
        if (keys['ArrowUp']) {
          newX += Math.sin(newRotation) * speed;
          newY -= Math.cos(newRotation) * speed;
        }
        if (keys['ArrowDown']) {
          newX -= Math.sin(newRotation) * speed;
          newY += Math.cos(newRotation) * speed;
        }

        // Keep car in bounds
        newX = Math.max(50, Math.min(350, newX));
        newY = Math.max(200, Math.min(600, newY));

        return { x: newX, y: newY, rotation: newRotation };
      });

      // Update camera to follow car
      setCameraOffset({ x: 0, y: 0 });
    }, 1000 / 60);

    return () => clearInterval(updateInterval);
  }, [gameStarted, keys]);

  // Draw 3D environment
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');

    const draw = () => {
      // Clear canvas
      ctx.fillStyle = '#87CEEB'; // Sky blue
      ctx.fillRect(0, 0, 400, 300);

      // Draw ground
      ctx.fillStyle = '#228B22'; // Forest green
      ctx.fillRect(0, HORIZON_Y, 400, 200);

      // Draw road in 3D perspective
      ctx.fillStyle = '#555555';
      ctx.beginPath();
      ctx.moveTo(VANISH_POINT.x - 50, HORIZON_Y);
      ctx.lineTo(50, 300);
      ctx.lineTo(350, 300);
      ctx.lineTo(VANISH_POINT.x + 50, HORIZON_Y);
      ctx.closePath();
      ctx.fill();

      // Draw road lines
      ctx.strokeStyle = '#FFFFFF';
      ctx.lineWidth = 2;
      ctx.setLineDash([10, 10]);
      ctx.beginPath();
      ctx.moveTo(VANISH_POINT.x, HORIZON_Y);
      ctx.lineTo(200, 300);
      ctx.stroke();
      ctx.setLineDash([]);

      // Draw trees in 3D perspective
      const trees = [
        { x: 80, z: 0.3 }, { x: 320, z: 0.3 },
        { x: 60, z: 0.5 }, { x: 340, z: 0.5 },
        { x: 40, z: 0.7 }, { x: 360, z: 0.7 },
        { x: 100, z: 0.2 }, { x: 300, z: 0.2 }
      ];

      trees.forEach(tree => {
        const scale = 1 - tree.z;
        const treeX = VANISH_POINT.x + (tree.x - VANISH_POINT.x) * scale;
        const treeY = HORIZON_Y + (300 - HORIZON_Y) * scale;
        const treeSize = 30 * scale;

        // Tree trunk
        ctx.fillStyle = '#8B4513';
        ctx.fillRect(treeX - treeSize/4, treeY - treeSize, treeSize/2, treeSize);

        // Tree foliage
        ctx.fillStyle = '#228B22';
        ctx.beginPath();
        ctx.arc(treeX, treeY - treeSize, treeSize, 0, Math.PI * 2);
        ctx.fill();
      });

      // Draw car
      if (gameStarted) {
        ctx.save();
        ctx.translate(carPosition.x, carPosition.y);
        ctx.rotate(carPosition.rotation);

        // Car body
        ctx.fillStyle = '#FF4444';
        ctx.fillRect(-15, -25, 30, 50);

        // Car windows
        ctx.fillStyle = '#4444FF';
        ctx.fillRect(-10, -20, 20, 15);

        // Car wheels
        ctx.fillStyle = '#000000';
        ctx.fillRect(-18, -20, 6, 10);
        ctx.fillRect(12, -20, 6, 10);
        ctx.fillRect(-18, 15, 6, 10);
        ctx.fillRect(12, 15, 6, 10);

        ctx.restore();
      }

      requestAnimationFrame(draw);
    };

    draw();
  }, [gameStarted, carPosition, theme]);

  const startDriving = () => {
    setGameStarted(true);
  };

  return (
    <div style={{ position: 'relative', width: '100%', height: '100vh', overflow: 'hidden' }}>
      {/* 3D Environment Canvas */}
      <canvas
        ref={canvasRef}
        width={400}
        height={300}
        style={{
          position: 'fixed',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          zIndex: 1
        }}
      />

      {/* Content Overlay */}
      <div
        style={{
          position: 'relative',
          zIndex: 2,
          pointerEvents: gameStarted ? 'none' : 'auto',
          transition: 'opacity 0.3s',
          opacity: gameStarted ? 0.3 : 1
        }}
      >
        {children}
      </div>

      {/* Driving Controls */}
      {gameStarted && (
        <div
          style={{
            position: 'fixed',
            bottom: 20,
            left: 20,
            zIndex: 3,
            background: 'rgba(0,0,0,0.7)',
            color: 'white',
            padding: '15px',
            borderRadius: '10px',
            fontFamily: "'Space Mono', monospace",
            fontSize: '12px'
          }}
        >
          <div>🚗 Driving Mode Active</div>
          <div style={{ fontSize: '10px', marginTop: '5px', opacity: 0.8 }}>
            Arrow Keys: Drive | ESC: Exit
          </div>
        </div>
      )}

      {/* Start Driving Button */}
      {!gameStarted && (
        <div
          style={{
            position: 'fixed',
            top: 20,
            right: 20,
            zIndex: 3
          }}
        >
          <button
            onClick={startDriving}
            style={{
              background: theme.accent,
              color: theme.bg,
              border: 'none',
              padding: '12px 24px',
              borderRadius: '25px',
              fontSize: '12px',
              fontWeight: 'bold',
              cursor: 'pointer',
              fontFamily: "'Space Mono', monospace",
              boxShadow: '0 4px 15px rgba(0,0,0,0.3)'
            }}
          >
            🚗 Start Driving
          </button>
        </div>
      )}
    </div>
  );
}

